 public sealed class CombatFollowupTests
 {
  const string Reports="Tools/IronRequiem/Reports/CombatFollowup";PlayerCharacterController player;bool background;float capture;
  [UnitySetUp]public IEnumerator Setup(){capture=Time.captureDeltaTime;background=Application.runInBackground;Application.runInBackground=true;Time.captureDeltaTime=0;Time.timeScale=1;EditorSceneManager.LoadSceneInPlayMode(File.ReadAllText(Reports+"/phase.txt")=="final"?"Assets/IronRequiem/Scenes/CombatFollowupLab.unity":"Assets/IronRequiem/Scenes/EnemyRangeBurstLab.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;var menu=Object.FindAnyObjectByType<CombatLabMenu>();menu.BeginGame();menu.enabled=false;Object.FindAnyObjectByType<CombatTwoRoomsLab>().enabled=false;player=Object.FindAnyObjectByType<PlayerCharacterController>();player.enabled=false;player.GetComponent<Health>().Invincible=true;foreach(var c in Object.FindObjectsByType<Collider>())if(!c.transform.IsChildOf(player.transform)&&!(c.bounds.size.y<2&&c.bounds.size.x>20&&c.bounds.size.z>20))c.enabled=false;Move(new Vector3(0,.03f,-17));yield return null;}
  void Move(Vector3 p){var c=player.GetComponent<CharacterController>();c.enabled=false;player.transform.position=p;c.enabled=true;player.CharacterVelocity=Vector3.zero;Physics.SyncTransforms();}
  [UnityTearDown]public IEnumerator Cleanup(){Time.timeScale=1;Time.captureDeltaTime=capture;AudioListener.pause=false;var scene=SceneManager.GetActiveScene();SceneManager.SetActiveScene(SceneManager.CreateScene("FollowupCleanup"+Time.frameCount));yield return SceneManager.UnloadSceneAsync(scene);Application.runInBackground=background;}
  [Serializable]sealed class Perf {public string phase,environment,resolution,gpu,quality;public int vsync,targetFps,enemies,frames,shots,collections;public double playerLoopMeanMs,editorLoopMeanMs,renderLoopMeanMs;public double audioLookupBytes,audioLookupMs,medianMs,p95Ms,p99Ms,maxMs,over33Percent,gcBytesPerFrame;public string limitation="Editor only; short stationary 12-enemy shooting workload. No Player validation, no GPU counters, not proof that all stutters are resolved.";}
  static double P(List<double> a,float p)=>a[Mathf.Clamp((int)((a.Count-1)*p),0,a.Count-1)];
  [UnityTest]public IEnumerator CapturePerformance()
  {
   var phase=File.ReadAllText(Reports+"/phase.txt");var result=new Perf{phase=phase,environment="Unity Editor",resolution=Screen.width+"x"+Screen.height,gpu=SystemInfo.graphicsDeviceName,quality=QualitySettings.names[QualitySettings.GetQualityLevel()],vsync=QualitySettings.vSyncCount,targetFps=Application.targetFrameRate,enemies=12};
   AudioUtility.GetAudioGroup(AudioUtility.AudioGroups.WeaponShoot);var watch=System.Diagnostics.Stopwatch.StartNew();long start=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<1000;i++)AudioUtility.GetAudioGroup(AudioUtility.AudioGroups.WeaponShoot);result.audioLookupBytes=GC.GetAllocatedBytesForCurrentThread()-start;result.audioLookupMs=watch.Elapsed.TotalMilliseconds;
   var enemies=new List<EnemyController>();for(int i=0;i<12;i++){string name=i<4?"BigBot_Burst_v10":"T07_HitFeedback_v04";var go=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/IronRequiem/Prefabs/EnemyRange/"+name+"_Fast_Range.prefab"),new Vector3((i%4-1.5f)*7,0,5+(i/4)*6),Quaternion.Euler(0,180,0));enemies.Add(go.GetComponent<EnemyController>());foreach(var w in go.GetComponentsInChildren<WeaponController>(true))w.OnShoot+=()=>result.shots++;}yield return null;yield return null;foreach(var e in enemies){var m=e.GetComponent<EnemyMobile>();if(m)m.enabled=false;if(e.NavMeshAgent.isOnNavMesh)e.NavMeshAgent.isStopped=true;}
   float warm=Time.realtimeSinceStartup+3;while(Time.realtimeSinceStartup<warm){foreach(var e in enemies){var b=e.GetComponent<BigBotCombat>();if(b)b.RequestAttack();else if(e.KnownDetectedTarget)e.TryAtack(e.KnownDetectedTarget.transform.position);}yield return null;}
   var frames=new List<double>(5000);long bytes=0,playerNanos=0,editorNanos=0,renderNanos=0;bool playerValid=false,editorValid=false,renderValid=false;int collections=GC.CollectionCount(0);double previous=Time.realtimeSinceStartupAsDouble;float end=Time.realtimeSinceStartup+20;
   using(var playerLoop=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Internal,"PlayerLoop",1))
   using(var editorLoop=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Internal,"EditorLoop",1))
   using(var renderLoop=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Render,"RenderPipelineManager.DoRenderLoop_Internal",1))
   using(var recorder=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Memory,"GC Allocated In Frame",1))while(Time.realtimeSinceStartup<end){foreach(var e in enemies){var b=e.GetComponent<BigBotCombat>();if(b)b.RequestAttack();else if(e.KnownDetectedTarget)e.TryAtack(e.KnownDetectedTarget.transform.position);}yield return null;double now=Time.realtimeSinceStartupAsDouble;frames.Add((now-previous)*1000);previous=now;if(recorder.Valid)bytes+=recorder.LastValue;if(playerLoop.Valid){playerNanos+=playerLoop.LastValue;playerValid=true;}if(editorLoop.Valid){editorNanos+=editorLoop.LastValue;editorValid=true;}if(renderLoop.Valid){renderNanos+=renderLoop.LastValue;renderValid=true;}}
   result.playerLoopMeanMs=playerValid?playerNanos/1e6/frames.Count:-1;result.editorLoopMeanMs=editorValid?editorNanos/1e6/frames.Count:-1;result.renderLoopMeanMs=renderValid?renderNanos/1e6/frames.Count:-1;result.collections=GC.CollectionCount(0)-collections;result.frames=frames.Count;result.gcBytesPerFrame=bytes/(double)frames.Count;result.over33Percent=frames.Count(v=>v>33.33)*100d/frames.Count;frames.Sort();result.medianMs=P(frames,.5f);result.p95Ms=P(frames,.95f);result.p99Ms=P(frames,.99f);result.maxMs=frames.Last();File.WriteAllText(Reports+"/"+phase+"-performance.json",JsonUtility.ToJson(result,true));Assert.That(result.shots,Is.GreaterThan(20));
  }
  IEnumerator Spawn(string name)
  {
   var go=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/IronRequiem/Prefabs/CombatFollowup/"+name+".prefab"),new Vector3(-10,0,5),Quaternion.Euler(0,180,0));yield return null;yield return null;
   var e=go.GetComponent<EnemyController>();var m=go.GetComponent<EnemyMobile>();if(m)m.enabled=false;if(e.NavMeshAgent.isOnNavMesh)e.NavMeshAgent.isStopped=true;current=go;
  }
  GameObject current;
  void Aim(float gap=1.2f){var box=current.GetComponent<Collider>();Move(new Vector3(box.bounds.center.x,.03f,box.bounds.min.z-gap));player.PlayerCamera.transform.LookAt(box.bounds.center);Physics.SyncTransforms();Cursor.lockState=CursorLockMode.Locked;}
  [UnityTest]public IEnumerator ExecutionProtectsT07AndExpiresWithoutChangingGodMode()
  {
   Time.captureDeltaTime=1f/60;yield return Spawn("T07_HitFeedback_v04");var e=current.GetComponent<EnemyController>();e.enabled=false;current.GetComponent<Health>().TakeDamage(current.GetComponent<Health>().MaxHealth*.3f,player.gameObject);Aim();yield return null;var hp=player.GetComponent<Health>();hp.Invincible=false;float before=hp.CurrentHealth;Assert.That(player.GetComponent<StolenWeaponCarrier>().TryExecute(current.GetComponent<EnemyExecutionSource>()),Is.True);
   var hands=player.GetComponent<ProtagonistHandsPresentation>();Assert.That(hands.IsDisarming,Is.True);float timeout=Time.time+3;int attempts=0;while(hands.IsDisarming&&Time.time<timeout){hp.TakeDamage(100,current);attempts++;Assert.That(hp.CurrentHealth,Is.EqualTo(before));yield return null;}Assert.That(hands.IsDisarming,Is.False);Assert.That(attempts,Is.GreaterThan(20));hp.TakeDamage(100,current);Assert.That(hp.CurrentHealth,Is.EqualTo(before));yield return new WaitForSeconds(2.15f);hp.TakeDamage(1,current);Assert.That(hp.CurrentHealth,Is.EqualTo(before-1));hp.Invincible=true;yield return new WaitForSeconds(.2f);hp.TakeDamage(100,current);Assert.That(hp.CurrentHealth,Is.EqualTo(before-1));File.WriteAllText(Reports+"/t07-protection.txt","Real carrier execution: incoming damage blocked throughout hand animation and post-execution grace2s; damage resumes after expiry; preexisting god mode preserved.");
  }
  [UnityTest]public IEnumerator BigExecutionProtectsThenStolenRocketMatchesEnemy()
  {
   Time.captureDeltaTime=1f/60;yield return Spawn("BigBot_Burst_v10");var bot=current.GetComponent<BigBotCombat>();var e=current.GetComponent<EnemyController>();bot.enabled=false;e.enabled=false;current.GetComponent<Health>().TakeDamage(current.GetComponent<Health>().MaxHealth*.3f,player.gameObject);Aim();player.enabled=true;yield return null;var hp=player.GetComponent<Health>();hp.Invincible=false;float before=hp.CurrentHealth;var carrier=player.GetComponent<StolenWeaponCarrier>();Assert.That(carrier.TryExecute(current.GetComponent<EnemyExecutionSource>()),Is.True);var sequence=player.GetComponent<BigBotExecutionSequence>();Assert.That(sequence.IsRunning,Is.True);float timeout=Time.time+5;while(sequence.IsRunning&&Time.time<timeout){hp.TakeDamage(100,current);Assert.That(hp.CurrentHealth,Is.EqualTo(before));yield return null;}Assert.That(sequence.IsRunning,Is.False);Assert.That(sequence.ShotCount,Is.EqualTo(1));hp.TakeDamage(100,current);Assert.That(hp.CurrentHealth,Is.EqualTo(before));
   player.enabled=false;var weapon=carrier.Held.EquippedWeapon;var projectile=weapon.ProjectilePrefab.GetComponent<ProjectileStandard>();var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/IronRequiem/Prefabs/EnemyRange/BigBot_Burst_v10_Fast_Range.prefab").GetComponent<BigBotCombat>();Assert.That(PrefabUtility.GetCorrespondingObjectFromSource(projectile.gameObject),Is.SameAs(original.Cannons[0].ProjectilePrefab.gameObject));Assert.That(projectile.Speed,Is.EqualTo(original.ProjectileSpeed));Assert.That(projectile.Damage,Is.EqualTo(30));Assert.That(projectile.AreaOfDamage.AreaOfEffectDistance,Is.EqualTo(2.6f));var burst=weapon.GetComponent<CannonBurstShot>();Assert.That(burst.BurstCount,Is.EqualTo(3));Assert.That(carrier.Held.Ammo.Capacity,Is.EqualTo(120));player.PlayerCamera.transform.rotation=Quaternion.identity;yield return new WaitForSeconds(.8f);float energy=carrier.Held.Ammo.Remaining;weapon.HandleShootInputs(true,true,false);float until=Time.time+.7f;while(Time.time<until){weapon.HandleShootInputs(false,false,false);yield return null;}Assert.That(burst.ShotsFired,Is.EqualTo(3));Assert.That(carrier.Held.Ammo.Remaining,Is.EqualTo(energy-36));yield return new WaitForSeconds(2);hp.TakeDamage(1,null);Assert.That(hp.CurrentHealth,Is.EqualTo(before-1));File.WriteAllText(Reports+"/big-protection-rocket.txt","Real leap/rip/shot/dismount sequence protected against repeated incoming damage. Grace expires. Player rocket variant inherits enemy geometry/materials/trail, speed22 and travel48; damage30/radius2.6 retained. Three actual player shots spent36 energy from120.");
  }
  [UnityTest]public IEnumerator T07ChargesReleasesAndCancelsAtWallAndDeath()
  {
   Time.captureDeltaTime=1f/60;Move(new Vector3(-10,.03f,-5));yield return Spawn("T07_HitFeedback_v04");var e=current.GetComponent<EnemyController>();var weapon=e.GetCurrentWeapon();int shots=0;float power=-1;weapon.OnShoot+=()=>{shots++;power=weapon.CurrentCharge;};var visual=current.GetComponent<EnemyCannonChargePresentation>();yield return null;Assert.That(e.IsSeeingTarget,Is.True);Assert.That(e.TryAtack(player.GetComponent<Actor>().AimPoint.position),Is.False);float began=Time.time;while(Time.time-began<1.1f){e.TryAtack(player.GetComponent<Actor>().AimPoint.position);yield return null;}Assert.That(shots,Is.Zero);Assert.That(visual.IsVisible,Is.True);while(shots==0&&Time.time-began<1.5f){e.TryAtack(player.GetComponent<Actor>().AimPoint.position);yield return null;}Assert.That(shots,Is.EqualTo(1));Assert.That(power,Is.EqualTo(1));var p=weapon.ProjectilePrefab.GetComponent<ProjectileStandard>();Assert.That(p.GetComponent<ChargedProjectileDamage>().MaximumDamage,Is.EqualTo(8));Assert.That(p.Speed,Is.EqualTo(40));
   yield return new WaitForSeconds(weapon.DelayBetweenShots+.05f);for(int i=0;i<20;i++){e.TryAtack(player.GetComponent<Actor>().AimPoint.position);yield return null;}Assert.That(visual.IsVisible,Is.True);var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=new Vector3(-10,2,0);wall.transform.localScale=new Vector3(12,6,.5f);Physics.SyncTransforms();for(int i=0;i<90;i++){e.TryAtack(player.GetComponent<Actor>().AimPoint.position);yield return null;}Assert.That(shots,Is.EqualTo(1));Assert.That(visual.IsVisible,Is.False);Object.Destroy(wall);yield return null;yield return null;for(int i=0;i<20;i++){e.TryAtack(player.GetComponent<Actor>().AimPoint.position);yield return null;}Assert.That(visual.IsVisible,Is.True);current.GetComponent<Health>().Kill();yield return null;Assert.That(visual.IsVisible,Is.False);yield return new WaitForSeconds(.5f);Assert.That(shots,Is.EqualTo(1));File.WriteAllText(Reports+"/t07-charge.txt","Native EnemyController charging1.2s at real muzzle. No early shot; full charge1 projectile. Wall during next charge cancels without shot; reacquisition then death cancels and clears VFX. Damage8, speed40, range12.5 retained.");
  }
  [UnityTest]public IEnumerator MixerCacheRetainsRoutingAndNullClipIsSafe()
  {
   var group=AudioUtility.GetAudioGroup(AudioUtility.AudioGroups.WeaponShoot);Assert.That(group,Is.Not.Null);for(int i=0;i<1000;i++)Assert.That(AudioUtility.GetAudioGroup(AudioUtility.AudioGroups.WeaponShoot),Is.SameAs(group));int before=Object.FindObjectsByType<AudioSource>().Length;AudioUtility.CreateSFX(null,Vector3.zero,AudioUtility.AudioGroups.Impact,1);yield return null;Assert.That(Object.FindObjectsByType<AudioSource>().Length,Is.EqualTo(before));File.WriteAllText(Reports+"/audio-cache.txt","1000 lookups retain exact existing mixer routing; null clip creates no sound object. Tested pooled audio candidate rejected after worse frame times; final runtime retains native one-shot lifecycle.");
  } }
